mapper.sql:
WHERE d.kind = #{q.kind}
AND d.create_by = #{scope.userId}
AND d.doc_type = #{q.docType}

    AND d.status IN #{s}

AND (d.from_warehouse_id = #{q.warehouseId} OR d.to_warehouse_id = #{q.warehouseId})
AND d.partner_id = #{q.partnerId}
AND d.doc_date >= #{q.docDateFrom}
AND d.doc_date <= #{q.docDateTo}

    AND d.id IN #{id}

choose.when:


(
    SELECT kd.* FROM inv_doc kd
    WHERE (upper(kd.no) LIKE #{keywordCode}
        OR upper(kd.no) IN #{code})
    UNION
    SELECT kd.* FROM inv_doc kd
    WHERE kd.source_no IS NOT NULL AND (upper(kd.source_no) LIKE #{keywordCode}
        OR upper(kd.source_no) IN #{code})
    UNION
    SELECT kd.* FROM inv_doc kd
    WHERE kd.supplier_delivery_no IS NOT NULL AND (upper(kd.supplier_delivery_no) LIKE #{keywordCode}
        OR upper(kd.supplier_delivery_no) IN #{code})
    UNION
    SELECT kd.* FROM inv_doc kd
    WHERE kd.logistics_no IS NOT NULL AND (upper(kd.logistics_no) LIKE #{keywordCode}
        OR upper(kd.logistics_no) IN #{code})
    UNION
    SELECT kd.* FROM inv_doc_item ki JOIN inv_doc kd ON kd.id = ki.doc_id WHERE ki.material_sku_id IN (
        SELECT k.id FROM bas_material_sku k WHERE upper(k.code) LIKE #{keywordCode}
        OR upper(k.code) IN #{code}
        UNION
        SELECT k.id FROM bas_material m JOIN bas_material_sku k ON k.material_id=m.id
        WHERE upper(m.code) LIKE #{keywordCode} OR m.name ILIKE #{keywordContains}
        OR upper(m.code) IN #{code}
    )
    UNION
    SELECT kd.* FROM inv_doc_item ki JOIN inv_doc kd ON kd.id = ki.doc_id WHERE ki.dye_lot IS NOT NULL AND ki.dye_lot ILIKE #{keywordContains}
)
